# ─────────────────────────── pacing (narration is the clock) ───────────────────────────
def _elapsed(self):
    rt = getattr(getattr(self, "renderer", None), "time", None)
    return float(rt) if isinstance(rt, (int, float)) else 0.0


def _bid(self):
    return type(self).__name__.split("_")[0]


def until(self, phrase, lead=0.25):
    bid = _bid(self)
    n, target = _NARR.get(bid, ""), _TARGET.get(bid, 0)
    if not n or not target or phrase not in n:
        return
    gap = target * n.index(phrase) / len(n) - lead - _elapsed(self)
    if gap > 0.05:
        self.wait(gap)


def finish(self):
    target = _TARGET.get(_bid(self), 0)
    if not target:
        self.wait(2.0)
        return
    rest = target - _elapsed(self) - 0.08
    self.wait(rest if rest > 0.05 else 0.05)


def go(self, *anims, rt=0.6):
    """self.play, but a move that would overlap the beat's 44-56% window is shifted out of it."""
    target = _TARGET.get(_bid(self), 0)
    t = _elapsed(self)
    if target and t + rt > target - 0.12:
        rt = max(0.2, target - 0.12 - t)
    if target:
        w0, w1 = 0.44 * target, 0.56 * target
        if t < w1 and t + rt > w0:
            if w0 - t >= 0.45:
                rt = max(0.25, w0 - t - 0.08)
            else:
                self.wait(max(0.0, w1 - t) + 0.02)
    self.play(*anims, run_time=rt)


# ─────────────────────────── primitives ───────────────────────────
def T(s, size=34, color=INK, bold=False):
    return Text(s, font=SERIF, color=color, font_size=size, weight="BOLD" if bold else "NORMAL")


def M(s, size=48, color=INK):
    return MathTex(s, color=color, font_size=size)


def box(cx, cy, w, h, fill=CARD, stroke=SOFT, sw=4):
    if stroke == SOFT:
        stroke = GREYLINE        # GATE T 8.6b: a dark outline round a label reads as a second text run
    return RoundedRectangle(width=w, height=h, corner_radius=0.12, fill_color=fill, fill_opacity=1,
                            stroke_color=stroke, stroke_width=sw).move_to([cx, cy, 0])


def node(cx, cy, label, w=2.2, h=0.9, size=32, fill=CARD, stroke=SOFT, color=INK):
    t = T(label, size, color)
    w = max(w, t.width + 0.5)
    r = box(cx, cy, w, h, fill, stroke)
    t.move_to([cx, cy, 0])
    g = VGroup(r, t)
    g.rect, g.txt = r, t
    return g


def fbar(x0, y, w, h, color=BAR1):
    w = max(w, 0.02)
    return Rectangle(width=w, height=h, fill_color=color, fill_opacity=1, stroke_width=0, stroke_opacity=0).move_to([x0 + w / 2, y, 0])


def vbar(x, y0, h, w=1.0, color=BAR1):
    h = max(h, 0.03)
    return Rectangle(width=w, height=h, fill_color=color, fill_opacity=1, stroke_width=0, stroke_opacity=0).move_to([x, y0 + h / 2, 0])


def hline(x0, x1, y, color=GHOST, w=4):
    return Line([x0, y, 0], [x1, y, 0], color=color, stroke_width=w)


def vline(x, y0, y1, color=GHOST, w=4):
    return Line([x, y0, 0], [x, y1, 0], color=color, stroke_width=w)


def seg(p0, p1, color=INK, w=5):
    return Line([p0[0], p0[1], 0], [p1[0], p1[1], 0], color=color, stroke_width=w)


def arrow(p0, p1, color=SOFT, w=6):
    return Arrow([p0[0], p0[1], 0], [p1[0], p1[1], 0], buff=0.05, color=color, stroke_width=w, max_tip_length_to_length_ratio=0.22)


def check(x, y, s=0.2, color=INK, w=7):
    return VGroup(Line([x - s, y, 0], [x - s * 0.3, y - s * 0.75, 0], color=color, stroke_width=w),
                  Line([x - s * 0.3, y - s * 0.75, 0], [x + s * 1.1, y + s * 0.85, 0], color=color, stroke_width=w))


def cross(x, y, s=0.2, color=SOFT, w=6):
    return VGroup(Line([x - s, y + s, 0], [x + s, y - s, 0], color=color, stroke_width=w),
                  Line([x - s, y - s, 0], [x + s, y + s, 0], color=color, stroke_width=w))


def tdot(x, y, r=0.1):
    return Dot([x, y, 0], radius=r, color=TERRA)


def ring(cx, cy, w, h, color=DIM):
    return RoundedRectangle(width=w, height=h, corner_radius=0.1, stroke_color=color, stroke_width=4, fill_opacity=0).move_to([cx, cy, 0])


def dots(points, r=0.07, color=INK):
    return VGroup(*[Dot([x, y, 0], radius=r, color=color) for x, y in points])


def lab(s, x, y, size=32, color=INK, bold=False, edge=None):
    t = T(s, size, color, bold).move_to([x, y, 0])
    if edge is not None:
        t.move_to([x, y, 0], aligned_edge=edge)
    return t


# ─────────────────────────── recurring casts ───────────────────────────
class Gap:
    """Two outcome bars (group A dim, group B ink) with a bracket measuring the gap."""
    def __init__(self, cx, cy, ha, hb, w=0.9, sep=1.2, size=32, labels=True, base=None):
        self.cx, self.cy, self.w, self.sep, self.size, self.labels = cx, cy, w, sep, size, labels
        self.ha, self.hb = ha, hb
        self.g = self._build(ha, hb)

    def _build(self, ha, hb):
        cx, cy, w, s = self.cx, self.cy, self.w, self.sep
        a = vbar(cx - s / 2, cy, ha, w, BAR2); b = vbar(cx + s / 2, cy, hb, w, INK)
        base = hline(cx - s - w / 2, cx + s + w / 2 + 0.55, cy, SOFT, 4)
        top = max(ha, hb); lo = min(ha, hb)
        br = VGroup(seg((cx + s / 2 + w / 2 + 0.2, cy + lo), (cx + s / 2 + w / 2 + 0.2, cy + top), SOFT, 5),
                    seg((cx + s / 2 + w / 2 + 0.1, cy + lo), (cx + s / 2 + w / 2 + 0.3, cy + lo), SOFT, 5),
                    seg((cx + s / 2 + w / 2 + 0.1, cy + top), (cx + s / 2 + w / 2 + 0.3, cy + top), SOFT, 5))
        g = VGroup(a, b, base, br)
        if self.labels:
            g.add(T("A", self.size, INK).move_to([cx - s / 2, cy - 0.35, 0]), T("B", self.size, INK).move_to([cx + s / 2, cy - 0.35, 0]))
        return g

    def to(self, ha, hb):
        self.ha, self.hb = ha, hb
        return self._build(ha, hb)


def strip(labels, y, x0=-5.4, x1=5.4, w=2.0, h=0.85, size=32):
    n = len(labels)
    xs = [x0 + (x1 - x0) * i / (n - 1) for i in range(n)] if n > 1 else [(x0 + x1) / 2]
    nodes = [node(x, y, l, w, h, size) for x, l in zip(xs, labels)]
    arrows = [arrow((xs[i] + w / 2 + 0.05, y), (xs[i + 1] - w / 2 - 0.05, y), SOFT, 5) for i in range(n - 1)]
    return nodes, arrows, xs


def number_line(x0, x1, y):
    return VGroup(hline(x0, x1, y, SOFT, 5), *[vline(x0 + (x1 - x0) * i / 10, y - 0.09, y + 0.09, SOFT, 4) for i in range(11)])


def grid_dots(cx, cy, nx, ny, gap=0.3, r=0.075, color=INK):
    pts = [(cx + (i - (nx - 1) / 2) * gap, cy + (j - (ny - 1) / 2) * gap) for j in range(ny) for i in range(nx)]
    return VGroup(*[Dot([x, y, 0], radius=r, color=color) for x, y in pts])


