def _hist(samples, lo, hi, nb, x0, x1, y0, hmax, color=INK):
    cnt, _ = np.histogram(samples, bins=nb, range=(lo, hi))
    m = max(cnt.max(), 1); bw = (x1 - x0) / nb
    bars = VGroup(*[Rectangle(width=bw * 0.9, height=max(0.03, hmax * c / m), fill_color=color, fill_opacity=1, stroke_width=0).move_to([x0 + bw * (i + 0.5), y0 + max(0.03, hmax * c / m) / 2, 0]) for i, c in enumerate(cnt)])
    return bars


