def ladder(cx, cy, ghost3=True):
    rails = VGroup(vline(cx - 1.4, cy - 1.9, cy + 1.9, SOFT, 8), vline(cx + 1.4, cy - 1.9, cy + 1.9, SOFT, 8))
    rungs = VGroup(hline(cx - 1.4, cx + 1.4, cy - 1.3, INK, 8), hline(cx - 1.4, cx + 1.4, cy, INK, 8),
                   hline(cx - 1.4, cx + 1.4, cy + 1.3, BAR3 if ghost3 else INK, 8))
    return rails, rungs


