NODEPOS = {"A": (0.0, 3.0, "protected attribute", 3.6), "D": (-4.85, 1.5, "training sample", 2.4), "L": (-2.0, 1.5, "labels", 1.5),
           "P": (2.8, 1.5, "proxies", 1.7), "F": (-1.4, 0.1, "features", 1.8), "M": (-4.0, 0.1, "model", 1.6), "O": (-4.0, -1.3, "output", 1.6),
           "R": (0.2, -1.9, "reviewer", 2.0), "C": (4.6, -1.0, "threshold, appeals", 3.3), "K": (2.0, -3.0, "outcome", 2.0)}
EDGES = [("A", "P"), ("A", "D"), ("A", "L"), ("A", "R"), ("A", "C"), ("P", "F"), ("P", "R"), ("P", "C"), ("D", "M"), ("L", "M"), ("F", "M"),
         ("M", "O"), ("O", "R"), ("O", "C"), ("R", "K"), ("C", "K")]


class CGraph:
    def __init__(self):
        self.nodes = {k: node(x, y, t, w, 0.7, 32) for k, (x, y, t, w) in NODEPOS.items()}
        for n_ in self.nodes.values():
            n_.set_z_index(2)
        self.edges = {}
        for a, b in EDGES:
            pa = np.array(NODEPOS[a][:2] + (0,)); pb = np.array(NODEPOS[b][:2] + (0,))
            d = (pb - pa) / np.linalg.norm(pb - pa)
            def hit(k):
                hw = self.nodes[k].rect.width / 2 + 0.08; hh = 0.35 + 0.08
                return min(hw / max(abs(d[0]), 1e-6), hh / max(abs(d[1]), 1e-6))
            ea = pa + d * hit(a); eb = pb - d * hit(b)
            self.edges[(a, b)] = Arrow(ea, eb, buff=0, color=SOFT, stroke_width=3.5, max_tip_length_to_length_ratio=0.12, max_stroke_width_to_length_ratio=8).set_z_index(1)
        self.paths = EV["G"]["paths"]

    def all(self):
        return VGroup(*self.edges.values(), *self.nodes.values())

    def edge_set(self, path):
        return {(path[i], path[i + 1]) for i in range(len(path) - 1)}

    def state(self, blocked):
        """animations: blocked nodes fade, edges used only by blocked paths turn ghost, open ones turn ink."""
        open_paths = [p for p in self.paths if not any(n in p[1:-1] for n in blocked)]
        open_edges = set().union(*[self.edge_set(p) for p in open_paths]) if open_paths else set()
        anims = []
        for e, a in self.edges.items():
            anims.append(a.animate.set_color(INK if e in open_edges else GHOST))
        for k, n in self.nodes.items():
            anims.append(n.animate.set_opacity(0.4 if k in blocked else 1.0))
        return anims, len(open_paths)


